document.getElementById('menuToggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('packModal').addEventListener('click',event=>{if(event.target.id==='packModal')closeModal();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(document.getElementById('phoneOverlay').classList.contains('show'))closePhone();if(document.getElementById('unboxOverlay').classList.contains('show'))finishUnbox();if(document.getElementById('packModal').classList.contains('show'))closeModal();}});
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
render();

