125:   document.getElementById('sideLevel').textContent=`Level ${state.level}`;
126:   const next=UNLOCKS.find(u=>u.level>state.level);
127:   document.getElementById('sideNext').textContent=next?`Level ${next.level}`:'Max level';
128:   document.querySelectorAll('.locked-nav').forEach(el=>{
129:     const needed=Number(el.dataset.unlock);const locked=state.level<needed;
130:     el.classList.toggle('is-locked',locked);
131:     el.querySelector('.lock-icon').textContent=locked?'⌑':'✓';
132:   });
133:   const unlock=UNLOCKS.find(u=>u.level>state.level);
134:   document.getElementById('nextUnlockName').textContent=unlock?unlock.name:'All features unlocked';
135:   document.getElementById('nextUnlockLevel').textContent=unlock?`LVL ${unlock.level}`:'✦';
136:   document.getElementById('collectionTotal').textContent=ownedCount();
137:   document.getElementById('allCount').textContent=ownedCount();
138:   document.getElementById('journalCount').textContent=ownedCount();
139:   document.getElementById('storageCount').textContent=(state.deliveries||[]).length;
140:   document.getElementById('rebirthCount').textContent=state.rebirths;
141:   document.getElementById('rebirthRequirement').textContent=`Level ${Math.min(state.level,15)} / 15`;
142:   document.getElementById('rebirthProgress').style.width=Math.min(100,state.level/15*100)+'%';
143:   const rebirthButton=document.getElementById('rebirthButton');rebirthButton.disabled=state.level<15;rebirthButton.innerHTML=state.level>=15?'Rebirth now <span>↗</span>':'Rebirth unavailable <span>↗</span>';
144:   renderPacks();renderCollection();renderJournal();renderStorage();renderHunting();
