83: function tierWeight(tier,pack){
84:   let weights={Normal:56,Gold:19,Rare:12,Diamond:7,Godlike:3.3,Special:2,Secret:.7};
85:   if(pack==='moon'){weights={Normal:47,Gold:20,Rare:15,Diamond:9,Godlike:4.5,Special:3,Secret:1.5};}
