95:   const pack=PACKS.find(p=>p.id===packId)||PACKS[0];
96:   let pool=CARD_POOL.filter(c=>c.pack===packId);
97:   if(pool.length<3)pool=CARD_POOL;
98:   const weighted=pool.map(c=>({card:c,weight:tierWeight(c.tier,packId)}));
99:   const total=weighted.reduce((a,x)=>a+x.weight,0);let n=Math.random()*total;
100:   for(const entry of weighted){n-=entry.weight;if(n<=0)return entry.card;}
101:   return weighted[0].card;
102: }
